 * @param config - The process's own HTTP configuration, carrying `gatewayToken`.
 * @returns The asserted subject, or `undefined` when no valid assertion is present.
 */
export function assertedHttpSubject(headers, config) {
  try {
    if (config.gatewayToken === undefined) return undefined;
    const token = singleHeaderValue(headers, ASSERTED_GATEWAY_TOKEN_HEADER);
    if (token === undefined || !timingSafeStringEqual(token, config.gatewayToken)) return undefined;
    const subject = singleHeaderValue(headers, ASSERTED_SUBJECT_HEADER);
    if (subject === undefined || subject.length === 0 || subject.length > ASSERTED_SUBJECT_MAX_LENGTH) return undefined;
    return ASSERTED_SUBJECT_PATTERN.test(subject) ? subject : undefined;
  } catch {
    return undefined;
  }
}

/** Resolve one closed HTTP identity decision without exposing malformed input. */
export function resolveHttpRequestIdentity(headers, config) {
  try {
    if (config?.gatewayToken !== undefined) {
      const configuredToken = config.gatewayToken;
      if (typeof configuredToken !== "string" || configuredToken.length === 0) {
        return Object.freeze({ kind: "refused" });
      }
      const token = singleHeaderValue(headers, ASSERTED_GATEWAY_TOKEN_HEADER);
      const subject = singleHeaderValue(headers, ASSERTED_SUBJECT_HEADER);
      if (token === undefined || subject === undefined || subject.length === 0
        || subject.length > ASSERTED_SUBJECT_MAX_LENGTH
        || !ASSERTED_SUBJECT_PATTERN.test(subject)
        || !timingSafeStringEqual(token, configuredToken)) {
        return Object.freeze({ kind: "refused" });
      }
      return Object.freeze({ kind: "gateway", subject });
    }
    if (headers[ASSERTED_SUBJECT_HEADER] !== undefined
      || headers[ASSERTED_GATEWAY_TOKEN_HEADER] !== undefined) {
      return Object.freeze({ kind: "refused" });
    }
    return Object.freeze({ kind: "process" });
  } catch {
    return Object.freeze({ kind: "refused" });
  }
}
","clauses":["L-A01"]},{"path":"src/http/server.mjs","inputSha256":"8c9b6d7c7fa2b27e7da3a4df73d349c4d45c7417dcd37e6e3bfd1a1bd3bc390d","before":"import { assertedHttpSubject } from "@red-cup-engineering/metroplat/http-options";","after":"import { resolveHttpRequestIdentity } from "@red-cup-engineering/metroplat/http-options";","clauses":["L-A01","L-A02","L-A06"]},{"path":"src/http/server.mjs","inputSha256":"8c9b6d7c7fa2b27e7da3a4df73d349c4d45c7417dcd37e6e3bfd1a1bd3bc390d","before":"/**
 * Per-request dispatch identity: the gateway-asserted subject when the request
 * proves it (see `assertedHttpSubject`), else the process's own fixed subject.
 * The process subject invoking an operation asserted-only is refused downstream
 * by ordinary capability-standing authorization — no special-casing here.
 */
function requestDispatchOptions(req, options) {
  if (options.httpConfig === undefined) return options;
  const asserted = assertedHttpSubject(req.headers, options.httpConfig);
  if (asserted === undefined) return options;
  const baseCaller = isJsonRecord(options.caller) ? options.caller : {};
  return {
    ...options,
    subject: asserted,
    caller: { ...baseCaller, transport: "http", asserted: asserted !== options.subject },
  };
}

function claimSessionOptions(options) {
  return {
    ...(options.claimSession === undefined ? {} : { persistence: options.claimSession }),
    ...(options.lifecycle === undefined ? {} : { lifecycle: options.lifecycle }),
    now: options.now,
  };
}
","after":"/** Resolve one immutable dispatch-options snapshot for an ordinary HTTP request. */
function requestDispatchOptions(req, options) {
  const identity = resolveHttpRequestIdentity(req.headers, options.httpConfig);
  if (identity.kind === "refused") return undefined;
  const dispatchOptions = { ...options, gatewaySubjects: false };
  if (identity.kind === "process") return dispatchOptions;
  const baseCaller = isJsonRecord(options.caller) ? options.caller : {};
  return {
    ...dispatchOptions,
    subject: identity.subject,
    caller: { ...baseCaller, transport: "http", asserted: true },
  };
}

function writeAuthenticationRequired(res) {
  res.writeHead(401, { "content-type": "application/json", "cache-control": "no-store" });
  res.end("{\"error\":\"authentication-required\"}");
}

function claimSessionOptions(options) {
  return {
    ...(options.claimSession === undefined ? {} : { persistence: options.claimSession }),
    ...(options.lifecycle === undefined ? {} : { lifecycle: options.lifecycle }),
    resolveRequestIdentity: (req) => requestDispatchOptions(req, options),
    now: options.now,
  };
}
